static int snd_soc_component_initialize ( struct snd_soc_component * component , const struct snd_soc_component_driver * driver , struct device * dev ) { struct snd_soc_dapm_context * dapm ; component -> name = fmt_single_name ( dev , & component -> id ) ; if ( ! component -> name ) { dev_err ( dev , "ASoC: Failed to allocate name\n" ) ; return - ENOMEM ; } component -> dev = dev ; component -> driver = driver ; component -> probe = component -> driver -> probe ; component -> remove = component -> driver -> remove ; component -> suspend = component -> driver -> suspend ; component -> resume = component -> driver -> resume ; component -> pcm_new = component -> driver -> pcm_new ; component -> pcm_free = component -> driver -> pcm_free ; dapm = & component -> dapm ; dapm -> dev = dev ; dapm -> component = component ; dapm -> bias_level = SND_SOC_BIAS_OFF ; dapm -> idle_bias_off = true ; if ( driver -> seq_notifier ) { dapm -> seq_notifier = snd_soc_component_seq_notifier ; } if ( driver -> stream_event ) { dapm -> stream_event = snd_soc_component_stream_event ; } component -> controls = driver -> controls ; component -> num_controls = driver -> num_controls ; component -> dapm_widgets = driver -> dapm_widgets ; component -> num_dapm_widgets = driver -> num_dapm_widgets ; component -> dapm_routes = driver -> dapm_routes ; component -> num_dapm_routes = driver -> num_dapm_routes ; INIT_LIST_HEAD ( & component -> dai_list ) ; return 0 ; } 